/* The top edge is a slice of an ellipse three widths wide and 2R tall, centred R below the top:
   at the side edges it drops 1.4% of R, whatever the width. R = 1800px gives a 25px arc on
   phones, 3600px a 50px arc on desktop. The negative margin tucks the arc over the section
   above by the same depth. */
.prenuvo-arc {
  clip-path: ellipse(300% 1800px at 50% 1800px);
}
.prenuvo-arc-overlap {
  margin-top: -25px;
}
@media (min-width: 64rem) {
  .prenuvo-arc {
    clip-path: ellipse(300% 3600px at 50% 3600px);
  }
  .prenuvo-arc-overlap {
    margin-top: -50px;
  }
}

import type { ElementType, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./prenuvo-arc.css";

export interface PrenuvoArcProps {
  children?: ReactNode;
  /** the element to render (section by default) */
  as?: ElementType;
  /** tuck the arc over the section above (true by default) */
  overlap?: boolean;
  /** an id for in-page links */
  id?: string;
  className?: string;
}

export function PrenuvoArc({ children, as: Tag = "section", overlap = true, id, className }: PrenuvoArcProps) {
  return (
    <Tag id={id} className={cn("prenuvo-arc relative", overlap && "prenuvo-arc-overlap", className)}>
      {children}
    </Tag>
  );
}
